from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class OrderIn(BaseModel):
    customer_id: str
    amount: float

def get_repository():
    return real_database_repository  # remplacé par une doublure dans les tests

@app.post("/orders", status_code=201)
def create_order(order: OrderIn, repo=Depends(get_repository)) -> dict:
    if order.amount <= 0:
        raise HTTPException(status_code=422, detail="Montant invalide")
    order_id = repo.save(order.customer_id, order.amount)
    return {"order_id": order_id}

